  WorkerResponse dco_decode_worker_response(dynamic raw) {
    // Codec=Dco (DartCObject based), see doc to use other codecs
    switch (raw[0]) {
      case 0:
        return WorkerResponse_RenderedDMABuf(
          dco_decode_box_autoadd_bridge_shared_frame_info_linux(raw[1]),
        );
      case 1:
        return WorkerResponse_RenderedSharedTexture(
          dco_decode_box_autoadd_bridge_shared_frame_info(raw[1]),
        );
      case 2:
        return WorkerResponse_Scope(
          dco_decode_box_autoadd_bridge_scope_trace(raw[1]),
        );
      case 3:
        return WorkerResponse_Sampled(
          dco_decode_box_autoadd_bridge_sampled_pixels(raw[1]),
        );
      case 4:
        return WorkerResponse_PlaybackEnded();
      case 5:
        return WorkerResponse_CacheFilled();
      case 6:
        return WorkerResponse_RenderProgress(
          dco_decode_box_autoadd_bridge_render_progress(raw[1]),
        );
      case 7:
        return WorkerResponse_FrameProfile(
          dco_decode_box_autoadd_bridge_frame_profile(raw[1]),
        );
      case 8:
        return WorkerResponse_DeviceReset();
      default:
        throw Exception("unreachable");
